-- Funder categorization (relationship / products / size / paper / consolidation)
-- Produced by 5 parallel research agents, merged and normalized.
-- ADDITIVE ONLY: touches lenders.category and nothing else.

alter table public.lenders
  add column if not exists category jsonb;

comment on column public.lenders.category is
  'Funder categorization: relationship, products, size_tier, paper[], consolidation{type,confidence,note}, flags, known_for, deal_fit, confidence. Populated from the Aug 2026 funder research pass.';

create index if not exists lenders_category_gin on public.lenders using gin (category);

update public.lenders l
set category = v.cat
from (values
  ('e5e606c8-55dd-4490-9030-69214179a88b'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "real_estate_cre", "equipment_financing", "invoice_factoring"], "size_tier": "small_mid", "paper": ["A", "B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": true, "real_estate": true, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Lending marketplace — one app routed to 50+ partner lenders via its ABLE platform", "deal_fit": "Send the merchant you can't place yourself and want shopped broadly — especially multi-product needs (SBA, CRE, equipment, AR) where you don't have direct funder coverage.", "confidence": "high", "source_batch": "A", "website": "1west.com", "amount_note": "Broad; ~$500M funded across 10,000+ businesses (~$50K avg deal). No single published min/max — depends on the partner lender matched.", "notes": "Does NOT lend its own capital — confirmed by UCS lender review and 1West's own marketplace marketing. Qualification floor published as 6+ months TIB and $15K monthly revenue. 4.8 Trustpilot (~1,800 reviews). Has a formal '1West Partner Program' for ISOs with dedicated account executives. Because it is a competitor broker, treat as a last-resort placement, not a primary submission channel."}$cat$::jsonb),
  ('178e6cc5-d81c-44b6-a147-b76b2799374a'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "line_of_credit"], "size_tier": "mid_large", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Fast revenue-based financing — approval in ~3 hours, explicitly not credit-score-led", "deal_fit": "Mid-size revenue-based deal, $20K+/mo revenue, 1+ year TIB, weak-to-mid FICO but clean, consistent bank deposits. Good when speed is the selling point.", "confidence": "high", "source_batch": "A", "website": "bizcapfunding.com (newcocapitalgroup.com now 301-redirects here)", "amount_note": "Up to $2M (Bizcap US site). Third-party directory data still shows the NewCo book capped nearer $750K — assume $50K–$750K is the realistic working band and $2M is the exception.", "notes": "REBRAND CONFIRMED: newcocapitalgroup.com redirects to bizcapfunding.com — update the DB record name/URL. Published quals: EIN, 1+ year in business, $20K+ monthly revenue. Bizcap is the US arm of an Australian-origin funder. Legacy NewCo directory profile: FICO 550 floor, 24hr funding, strong in trucking/auto/logistics."}$cat$::jsonb),
  ('2d0c17c7-a33e-4d14-8006-239eef12aedc'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder", "white_label"], "products": ["mca"], "size_tier": "small_mid", "paper": ["C", "D"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "NYC same-day MCA for credit-challenged merchants; ISO-channel focused", "deal_fit": "Damaged-credit merchant who needs money today and won't survive a full underwrite. Small-to-mid ticket, multi-position tolerant.", "confidence": "med", "source_batch": "A", "website": "capitalexpressllc.com", "amount_note": "Site advertises up to $5,000,000; our DB has $5K–$1M. The low end ($5K) is credible, the $5M ceiling is almost certainly marketing. Treat as $5K–$1M.", "notes": "Explicitly markets to businesses 'with credit challenges' and same-day funding. ISO/partner channel confirmed via their own outbound ('Ready to work with a direct funding partner that understands the ISO...'). Max-amount claim is unverified and conflicts with our DB — do not quote $5M to a merchant. White-label designation carried over from our DB; I could not independently confirm a white-label program on the public site."}$cat$::jsonb),
  ('c15965db-d3c5-4424-b59d-adeb098d22fa'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["C", "D", "all_credit"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "No-FICO-requirement, high-risk MCA with same-day funding and early-payoff discounts", "deal_fit": "High-risk / low-FICO merchant, $10K–$500K, in healthcare, automotive, or e-commerce. Do NOT send non-profits or real-estate-sales businesses — explicitly excluded.", "confidence": "high", "source_batch": "A", "website": "cashablefund.com", "amount_note": "$10,000 – $500,000 (published)", "notes": "Site states 'no FICO requirements' outright and runs a formal ISO Agreement / partner onboarding path for brokers. Named industry exclusions: non-profits, real estate sales. Flexible repayment plus early payoff discount is a real closing lever."}$cat$::jsonb),
  ('9febee92-8e7b-48df-9a98-7d55a2a7759f'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "mid_large", "paper": ["A", "B", "C", "D"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "NYC fintech doing revenue-based financing across a very wide size band ($10K to $3M)", "deal_fit": "Your widest-band single submission — same funder can take a $15K micro deal or a $1M+ file. Good first stop when you don't yet know where the deal will land.", "confidence": "med", "source_batch": "A", "website": "cobaltfunding.com", "amount_note": "$10,000 – $3,000,000 (confirmed on their About page and LinkedIn)", "notes": "Funding range and NYC fintech positioning verified ($10K–$3M, 99 Wall Street, 24-hour decisions, nationwide). Pre-qualification under 24 hours. The syndication note in our DB is NOT confirmed anywhere public — treat as unverified. Paper tiers A–D come from our DB, not from their site; the site publishes no FICO floor. On deBanked's featured-provider list since 2025 (young relationship)."}$cat$::jsonb),
  ('f2469b6e-6fe6-49b6-8cde-9190912f046e'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "term_loan"], "size_tier": "small_mid", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Mid-ticket business financing with no collateral or appraisal — blanket lien on business assets only", "deal_fit": "Straightforward $20K–$400K working-capital file wanting a longer 6–24 month term rather than a short daily-pay MCA.", "confidence": "low", "source_batch": "A", "website": "corfingroup.com", "amount_note": "$20,000 – $400,000 (meta description) / up to $500,000 (page body). Terms 6–24 months.", "notes": "Thin public footprint. No ISO/partner page found, no published FICO floor, no revenue or TIB minimum, no deBanked profile located. Confirmed only: amount band, 6–24 month terms, 24-hour approvals, general UCC lien on business assets in lieu of specific collateral. Paper tier B/C carried from our DB — unverified. Verify commission and submission process by phone before sending a live file."}$cat$::jsonb),
  ('0901d781-fd58-4b73-82cc-3d544a50ef1e'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "mid_large", "paper": ["B", "C", "D", "all_credit"], "consolidation": {"type": "reverse_consolidation", "confidence": "high", "note": "No FICO minimum and no hard credit pull; underwrites on cash flow only. Wants 'solid revenue' with several open positions. Existing positions keep remitting on their original schedule — they are NOT paid off. All 50 states, explicitly including Texas (which many funders avoid). No published minimum position count, revenue floor, or term — each file is underwritten individually. Also offers: staged/tranched funding (a larger approval delivered in scheduled installments) Underwritten: in-house — they fund reverses with their own capital, not brokered out Evidence: dieselfunding.com/how-to-submit-deals and their broker guide both state they 'underwrite MCA reverse consolidations (reverses) in-house for merchants with stacked positions'."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": true}, "known_for": "Credit-blind MCA — no hard credit pulls, no FICO minimums at all", "deal_fit": "The merchant whose FICO kills the file everywhere else. Underwrites purely on bank performance; same-day deposit possible. Strong in restaurants, construction, retail.", "confidence": "med", "source_batch": "A", "website": "dieselfunding.com", "amount_note": "Our DB says $5K–$3M; the site publishes no range. The $5K floor is consistent with their credit-blind posture.", "notes": "Est. 2017, nationwide. 'No hard credit pull / no FICO minimums' is their explicit headline positioning — verified on site. They do run a partner channel (partnership link present in site nav) but the /iso path 404s; get the real ISO URL from a rep. Amount range unverified against the site."}$cat$::jsonb),
  ('a42d603c-2109-4d3c-b837-50eadacfb2d1'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "equipment_financing", "invoice_factoring"], "size_tier": "mid_large", "paper": ["A", "B", "C", "D"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": true, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "AI-assisted funding marketplace routing one application across 70+ lenders", "deal_fit": "Overflow / hard-to-place files you want shopped wide without burning your own funder relationships. No hard credit pull on intake.", "confidence": "high", "source_batch": "A", "website": "elitefunders.com", "amount_note": "$10,000 – $5,000,000 (published)", "notes": "This is a COMPETITOR BROKER, not a funder — same business model as MFunding. Placing deals here means splitting with another ISO. Their public lender directory (elitefunders.com/lenders/) is however an excellent free intel source: 72 lender profiles with min FICO, funding speed, max amount, and position tolerance — I used it to verify several funders in this batch. Worth bookmarking for the deal-matching cheat sheet."}$cat$::jsonb),
  ('6eef3ae4-c029-4683-a79c-b30e9e912941'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "term_loan"], "size_tier": "mid_large", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "100% ISO-driven direct funder — MCAs and term loans, no retail channel", "deal_fit": "Clean broker file $10K–$2M where you want a direct funder (no intermediary shaving the offer) and a term-loan option alongside the MCA.", "confidence": "med", "source_batch": "A", "website": "fantastic-funding.com", "amount_note": "$10,000 – $2,000,000 (published)", "notes": "Self-describes as a direct funder and '100% ISO driven' — meaning they take deals only from brokers, which is ideal for us. Advertise ~24-hour average approvals, competitive commissions, dedicated ISO support, volume-based structure. No published FICO floor, TIB, or revenue minimum — paper tier is inferred. Site is newly built (v0.app-generated), so this may be a young shop; verify funding capacity before sending a large file."}$cat$::jsonb),
  ('8fcda541-76cb-4d61-91ea-762c570842fa'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder", "referral_affiliate"], "products": ["mca", "line_of_credit"], "size_tier": "small_mid", "paper": ["B", "C"], "consolidation": {"type": ["true_consolidation/payoff", "reverse_consolidation"], "confidence": "high", "note": "Dedicated product page covering BOTH structures — the only funder in this batch offering both. Process: apply, they review existing obligations, then consolidate into a new payment structure within 24-72 hours. No hard credit pull. No published minimum position count, credit floor, revenue, or TIB minimum. Also offers: credit card split funding (repayment as a share of card batches) Underwritten: unclear whether funded in-house or placed — verify with rep Evidence: funderial.com/mca-consolidation — page titled 'MCA Consolidation & Reverse Consolidation Loans | Reduce Daily Payments'."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": true}, "known_for": "Credit card split funding — MCA repaid as a share of card batches, not fixed ACH debits", "deal_fit": "Merchant with heavy CREDIT CARD volume (restaurant, retail, salon) who wants repayment tied to card sales rather than a daily fixed ACH. That split structure is their differentiator — send card-heavy files here.", "confidence": "med", "source_batch": "A", "website": "funderial.com", "amount_note": "Not published. $2B+ funded across 20,000+ businesses implies ~$100K average deal.", "notes": "The card-split product is the reason to keep them on the list; it's a genuinely different repayment structure that saves deals where a fixed daily debit would break the merchant. No hard credit pull, same-day funding for qualified files. They run both a partner program and a referral path ('become a partner' / referral opportunities). No published amount range, FICO floor, TIB, or revenue minimum — all unverified."}$cat$::jsonb),
  ('076e426f-07e4-485c-a811-1803dd18b035'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "mid_large", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "4-hour approvals with an A+ BBB rating — one of the more reputable mid-tier MCA funders", "deal_fit": "Mid-tier file: 6+ months TIB, $20K+/mo revenue, FICO 550+. NOTE THE SECTOR RULES — trucking needs 3 years TIB and construction needs $1M+ revenue. Don't waste a submission on a young trucking file.", "confidence": "high", "source_batch": "A", "website": "fundkite.com", "amount_note": "$10,000 – $2,000,000 advertised; independent directory data puts the practical max nearer $500K.", "notes": "Published quals verified on site: 6 months minimum operation, $20K+ monthly revenue, 550+ credit score, approval in as little as 4 hours, funding 24–48 hours, est. 2015, A+ BBB. Independent directory lists a 580 FICO floor and the trucking-3yr / construction-$1M sector overlays — those overlays are the highest-value fact here for deal matching."}$cat$::jsonb),
  ('e5516b47-9167-4236-895c-0a108f0f7352'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder", "marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "real_estate_cre", "equipment_financing"], "size_tier": "jumbo", "paper": ["B", "C", "D", "all_credit"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": true, "real_estate": true, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "The real-estate play — hard money, bridge, and rental investment loans alongside MCA, with no minimum credit score", "deal_fit": "ANY commercial real estate or hard-money file — this is the CRE outlet in this batch. Also the home for a low-credit merchant who needs more than an MCA can carry. Miami-based with a real Hispanic-market presence, which pairs with the Phoenix/Miami Spanish campaigns.", "confidence": "med", "source_batch": "A", "website": "gokapital.com", "amount_note": "Business: $20,000–$30,000 minimum up to $50M. Real estate: $100,000 – $50M, LTV up to 80%, terms to 30 years.", "notes": "Verified: 'no minimum credit score', 50-state coverage, 24-hour approvals, A+ BBB, explicit minority-owned-business focus, and the full RE product shelf (hard money, rental investment, residential and commercial). The $50M ceiling means they are brokering/table-funding the large RE deals, not funding all of it off balance sheet — hence the dual classification. Their /iso-program/ URL redirects to home; get the live ISO agreement from a rep. Commission structure not published."}$cat$::jsonb),
  ('75e0c40a-0ab7-40ab-a576-a527a3b1938f'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "line_of_credit", "equipment_financing"], "size_tier": "small_mid", "paper": ["B", "C"], "consolidation": {"type": "true_consolidation/payoff", "confidence": "high", "note": "'Cash Advance Consolidation' is a named product line on their homepage: combines multiple advance payments into one payment and lowers the effective rate. This is a genuine payoff/rollup, NOT a reverse. No prepayment penalty. Brooklyn NY, all 50 states, $150M+ funded since 2016. No published minimum position count, credit floor, or revenue minimum. Underwritten: in-house (self-describes as a direct lender) Evidence: greennotecapital.com homepage service list: 'Cash Advance Consolidation - Allows you to effectively lower your interest rate by combining multiple advances payments into one simple payment.'"}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": true}, "known_for": "Direct lender with a dedicated cash-advance CONSOLIDATION program and no prepayment penalties", "deal_fit": "Stacked merchant carrying multiple advances who needs them rolled into one — consolidation is an advertised product line, not an exception. Also good where the merchant may pay off early (no prepay penalty).", "confidence": "med", "source_batch": "A", "website": "greennotecapital.com", "amount_note": "$25,000+ (our DB). Site publishes no ceiling; $150M+ funded since 2016 across 40 industries.", "notes": "Self-identifies as a direct lender, founded 2016, $150M+ funded, 40 industries, nationwide. Consolidation is explicitly named in their own meta description ('Cash Advance Consolidation') — that's a verified product, and it's the reason to keep them close given how many UCC-sourced leads are already stacked. No prepayment penalty confirmed. No published FICO floor, TIB, revenue minimum, or max advance; ISO page not found at the obvious URL."}$cat$::jsonb),
  ('b4501fff-b5fb-4b49-9555-e62e42f6bdd8'::uuid, $cat${"relationship": "referral_affiliate", "relationships": ["referral_affiliate"], "products": ["startup_robs_401k", "sba_loan", "term_loan", "consumer"], "size_tier": "mid_large", "paper": ["A", "B"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": true, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": false, "consolidation": false}, "known_for": "ROBS — rolling a 401(k)/IRA into a startup or franchise purchase without tax penalty", "deal_fit": "NOT an MCA outlet. Send the STARTUP or franchise buyer with no business revenue yet but a real retirement account, and the SBA-quality borrower you can't monetize otherwise. This is a pure referral-out: we do not package stips or submit a file.", "confidence": "med", "source_batch": "A", "website": "guidantfinancial.com", "amount_note": "Driven by the client's retirement balance for ROBS (practically $50K+ to be worth doing); SBA up to $5M via lender partners.", "notes": "Category is unambiguous — 35,000+ businesses funded, 1,000+ franchise partners, dedicated partner tracks for business brokers, lenders, and franchisors, plus a Partner Center 'Refer a Client' portal. What I could NOT verify is the cash compensation to a referring broker: the public 'Refer a Friend' page pays in free 401(k) plan administration (up to $1,788), not cash. Confirm the actual referral fee with their BD team before counting on revenue. Timeline is weeks, not days — set closer expectations accordingly."}$cat$::jsonb),
  ('74792de1-ecbc-4d8b-b158-f91ef9fc8013'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["C", "D", "all_credit"], "consolidation": {"type": "reverse_consolidation", "confidence": "high", "note": "Built for 2nd-through-5th position merchants. FICO floor ~540, funds in ~48 hours, max ~$250K. Same-day funding available. No published minimum position count or revenue floor. Also offers: straight advances out to 36-week terms Underwritten: in-house Evidence: Confirmed three ways: their ISO rep's public posting ('Reverses and Straights to 36 Weeks'), a company job listing stating 'Reverse Consolidation available', and third-party directory listing them as a '2nd-5th position MCA specialist - Reverse consolidations'."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": true}, "known_for": "2nd-through-5th position specialist and reverse consolidations — takes the deeply stacked merchant", "deal_fit": "THE STACKED-MERCHANT OUTLET. Merchant already carrying 2–5 advances that everyone else declined; also reverse consolidations and straights out to 36 weeks. FICO ~540 floor, funds in 48 hours. Pairs directly with the UCC lead book, which is full of merchants with existing liens.", "confidence": "high", "source_batch": "A", "website": "highlandhillcap.com", "amount_note": "Up to ~$250,000 per independent directory data. No range published on their own site.", "notes": "Position tolerance (2nd–5th) and reverse consolidation confirmed both by third-party directory data and by their own ISO rep's public posting ('ISO Partnerships | Reverses and Straights to 36 Weeks | Same Day Funding'). Deerfield Beach, FL. ISO terms they advertise: dedicated ISO manager, next-day commission payouts, volume bonuses, 'no restrictions', decisions in hours. A job posting also references construction and bridge loans — treat those as unverified side products. Named as counterparty in at least one MCA lawsuit (Caruso v. Madison Advance, D. Nev.) — normal for the deep-stack segment but worth knowing."}$cat$::jsonb),
  ('c5a88bfa-86da-493f-b7d6-4968ec623c25'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["B", "C", "D", "all_credit"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "Underwrites future sales rather than credit history — 'poor credit is no problem'", "deal_fit": "Small-to-mid file $10K–$500K where credit is the blocker but the deposits are steady.", "confidence": "med", "source_batch": "A", "website": "instafunders.com", "amount_note": "$10,000 – $500,000 per their own site. Our DB says $25K–$2.5M — the DB figure appears WRONG; trust the site.", "notes": "DATA CONFLICT worth fixing in the DB: their site states $10,000–$500,000 in both the page copy and meta description; our record says $25K–$2.5M. Recommend correcting to $10K–$500K unless a rep confirms otherwise. They accept submissions from both merchants and ISOs directly. Three-step process (apply with recent cash flow docs → underwriter review → funds direct-deposited). No published FICO floor, TIB, or revenue minimum."}$cat$::jsonb),
  ('c5094486-c4bd-4c8a-8399-211efa2e4a48'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "line_of_credit"], "size_tier": "small_mid", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Small broker-channel MCA shop; fast approvals on modest tickets", "deal_fit": "Small ticket, roughly $15K–$100K. Their own funded examples: trucking $40K, medspa $75K, construction $100K, florist $15K — send files that shape.", "confidence": "low", "source_batch": "A", "website": "instagreencapital.com", "amount_note": "Our DB says $10K–$4M. Their own published funded-deal examples run $15K–$100K, which is the realistic band. The $4M ceiling is not credible.", "notes": "Small operation (Connecticut, 203 area code) with a thin web presence and no published quals of any kind — no FICO floor, TIB, revenue minimum, or amount range on the site. Broker channel is confirmed ('Helping brokers deliver funding to small businesses across America'). The size band above is inferred from the deals they advertise, not from a rate sheet. Get a written rate sheet before relying on them, and do not quote our DB's $4M ceiling."}$cat$::jsonb),
  ('4009c261-a881-4142-982a-6c36997edc37'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Long-established Funding Metrics platform — runs both the Lendini and Quick Fix Capital books", "deal_fit": "Small-to-mid revenue-based file, roughly $5K–$300K, FICO ~525+. Light stip load: business bank statements plus ID. Good for a fast small deal where you want an established name on the contract.", "confidence": "high", "source_batch": "A", "website": "lendini.com", "amount_note": "$5,100 – $300,000 per their site; independent directory data shows up to $500K across the Funding Metrics book.", "notes": "Funding Metrics is the parent; Lendini and Quick Fix Capital are its two portfolios — so a merchant may see either brand on the agreement. Buy rate starts around 1.25. Documented ISO partner program with dedicated account management and partner resources. Requirements vary BY STATE, which they call out explicitly — check state before promising terms. Directory FICO floor 525, 48-hour funding."}$cat$::jsonb),
  ('f67b7bd9-3bb1-48f7-8eac-feaaf83a5030'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator", "direct_funder"], "products": ["mca", "line_of_credit", "sba_loan"], "size_tier": "mid_large", "paper": ["A", "B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": true, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Broad product shelf with a claimed 90% acceptance rate and funding in as little as 2 hours", "deal_fit": "Use only after your direct funders decline. Multi-product need (MCA plus LOC plus SBA) with weak credit.", "confidence": "low", "source_batch": "A", "website": "nationwidecapitalsolution.com", "amount_note": "Conflicting: homepage says up to $1,000,000, page meta says $10K–$5,000,000, our DB says $10K–$5M. Assume $10K–$1M.", "notes": "LOWEST-CONFIDENCE RECORD IN THIS BATCH — flag for verification before sending a live file. Concerns: (1) carrying MCA + LOC + SBA-backed loans across a single small shop points to brokering rather than direct funding; (2) a claimed 90% acceptance rate with 'no strict credit or income checks' is an aggressive marketing claim, not an underwriting posture; (3) the max-amount figure contradicts itself on their own site; (4) two separate BBB profiles exist (Staten Island NY and Las Vegas NV), neither BBB-accredited. No ISO program, commission structure, or published quals found. Recommend a phone verification and a small test file before any volume."}$cat$::jsonb),
  ('be1f4618-18ec-45b4-9e36-1e600425212b'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "equipment_financing", "invoice_factoring"], "size_tier": "jumbo", "paper": ["A", "B"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": true, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Broad financing shelf for larger, better-qualified borrowers — SBA through asset-backed lending", "deal_fit": "The QUALITY file, not the distressed one. Hard floor: $500K+ annual revenue, 600+ FICO, 1+ year in business, business checking account. A-paper merchant wanting SBA, a real line of credit, or asset-backed structure rather than an MCA.", "confidence": "med", "source_batch": "A", "website": "relfi.co", "amount_note": "Up to $25,000,000 advertised; funding available within 24 hours.", "notes": "Their published eligibility bar is the most useful fact and is unusually clear: $500K minimum annual revenue, FICO 600+, 1 year TIB. That makes them the opposite end of the book from the C/D-paper funders in this batch — a genuinely different bucket, worth keeping for upmarket leads. Our DB tags them 'C paper, marketplace', which contradicts the 600 FICO floor — recommend correcting the paper tier. Relationship inferred from the product breadth (SBA + asset-backed + factoring + equipment is not one balance sheet); no /about or /partners page exists to confirm, and no ISO program or commission info was findable."}$cat$::jsonb),
  ('9e82cb23-5bb0-4a19-980b-28bb67431151'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Long-running San Diego MCA brand (est. 2008), now the premier funding arm of The LCF Group", "deal_fit": "Mid-tier MCA up to ~$400K, FICO 500+, approvals in as little as 30 minutes and funding in a day. Slightly better-quality file than you'd send to the LCF high-risk desk.", "confidence": "high", "source_batch": "A", "website": "reliantfunding.com", "amount_note": "Up to ~$400,000 per independent directory data", "notes": "OWNERSHIP CHANGE — IMPORTANT FOR THE DB: The LCF Group acquired Reliant Funding's strategic assets and licensing rights in September 2023 (reported by deBanked; both sites now serve shared LCF infrastructure). Reliant and The LCF Group in this same batch are ONE counterparty family, not two independent funders — do not treat a Reliant submission and an LCF submission as two shots at the deal, and check which entity appears on the merchant's agreement. LCF describes Reliant as its 'premier funding arm'. Directory data: FICO 500 floor, 24–48 hour funding, max ~$400K."}$cat$::jsonb),
  ('60cba11b-bf10-435d-b041-9feb3aa894bb'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["C", "D", "all_credit"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "Originally 'Last Chance Funding' — the high-risk MCA specialist with no minimum FICO", "deal_fit": "The file nobody else will touch. No FICO minimum. Their Express program funds in 2 HOURS on just a voided check, driver's license, and bank login — the lightest stip package in this batch, which makes it the right call when doc collection is what's killing the deal.", "confidence": "high", "source_batch": "A", "website": "thelcfgroup.com", "amount_note": "Up to ~$500,000 per independent directory data; $25K+ floor per our DB", "notes": "The Express program is the standout operational fact: 2-hour funding on three items, no bank statements required up front. Given that doc collection is the #1 funnel leak, this is a genuine save-the-deal option. Strong in auto, construction, and restaurants. Runs a formal ISO partner program (thelcfgroup.com/become-a-partner) advertising top commissions. NY-based. SEE THE RELIANT FUNDING NOTE — LCF owns Reliant since Sept 2023; same house."}$cat$::jsonb),
  ('ba3d03cc-6342-433d-a919-fb48cb009265'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "term_loan", "line_of_credit", "invoice_factoring"], "size_tier": "small_mid", "paper": ["B", "C", "D"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": false, "consolidation": false}, "known_for": "Small-ticket working capital with unusually long terms available (out to 36 months)", "deal_fit": "Small file $5K–$500K where the merchant needs a LONGER amortization than a standard 6–12 month MCA — the 3-to-36-month term range is the differentiator. No collateral required.", "confidence": "low", "source_batch": "A", "website": "trueadvance.biz", "amount_note": "$5,000 – $500,000 working capital; terms 3–36 months; application review 24–48 hours", "notes": "Verified from their site: $5K–$500K, 3–36 month terms, 24–48 hour review, no collateral, $200M+ claimed deployed, 96% claimed satisfaction. They also list term loans, invoice factoring, and lines of credit — for a shop this size those are probably brokered out rather than funded in-house, so treat the non-MCA products as unconfirmed. No ISO program, commission, FICO floor, TIB, or revenue minimum published; site last updated mid-2025. Paper tiers carried from our DB, unverified."}$cat$::jsonb),
  ('f73a9f64-d776-47a4-a0ac-b0a25a559faa'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator", "white_label"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "equipment_financing", "invoice_factoring"], "size_tier": "mid_large", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": true, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Established Garden City NY brokerage/marketplace (Jared Weitz) with white-label partner portals", "deal_fit": "Not a funding outlet — a competitor. The realistic use is their WHITE-LABEL PARTNER PORTAL if we ever want overflow capacity or product breadth we lack (SBA, factoring) without building funder relationships first.", "confidence": "high", "source_batch": "A", "website": "unitedcapitalsource.com", "amount_note": "Up to $5,000,000; $1.6B+ facilitated to date", "notes": "COMPETITOR, NOT A FUNDER — confirmed by deBanked's own profile ('an alternative-finance brokerage') and their site ('one of the nation's fastest-growing business financing marketplaces'). They offer partner portals with white-label links to ISOs, which is the same Sub-ISO model MFunding plans to run in Phase 3 — so they are both a potential channel and a direct competitor for Sub-ISO recruitment. Their lender-review library (unitedcapitalsource.com/business-loans/lender-reviews/) is a solid free research source; it's where the Reliant/LCF acquisition was corroborated. 1,600+ five-star reviews, no personal guarantee on some products."}$cat$::jsonb),
  ('87237386-39b8-4dcf-a53f-fc03d6aade0c'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder", "referral_affiliate"], "products": ["mca", "line_of_credit", "sba_loan", "equipment_financing"], "size_tier": "mid_large", "paper": ["B", "C", "D"], "consolidation": {"type": "reverse_consolidation", "confidence": "med", "note": "Mechanics: the funder deposits money into the merchant's account weekly to cover existing MCA payments, and the merchant makes one smaller weekly repayment over a longer term. Uplyft states the program can cut current payments by up to 50%. Eligibility minimums, rates, and terms are NOT published — must be obtained from a rep. Underwritten: unclear — may be placed through their partner network rather than funded in-house; verify Evidence: Uplyft maintains a dedicated reverse-consolidation resource page; independently corroborated by Finder's 2026 reverse-consolidation provider comparison, which lists Uplyft as a named provider."}, "flags": {"sba": true, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": true}, "known_for": "Miami-based high-volume MCA funder — $1.4B funded across 57,600+ businesses, 6-hour approvals", "deal_fit": "Workhorse MCA outlet with real volume behind it. Average deal $215K, so it handles bigger files than most of this batch. MCA is funded direct; SBA and equipment come through partners, so route those as referrals.", "confidence": "med", "source_batch": "A", "website": "uplyftcapital.com", "amount_note": "$5,000 – $5,000,000 advertised; average funding $215,000; the MCA product page caps at $500,000", "notes": "Track record is the strongest signal: $1.4B funded, 57,600+ businesses, 97% claimed satisfaction, approvals in as little as 6 hours, automatic revenue-based repayment. The $5K–$5M headline conflicts with the $500K cap shown on the MCA product page — the ceiling above ~$500K is almost certainly the partner-referred SBA/equipment side, which supports the dual classification. Our DB notes a referral arm; I found the product breadth consistent with that but the /partners URL 404s — get the current ISO and referral agreements from a rep. Commission structure not published."}$cat$::jsonb),
  ('ea733ace-66de-4804-8ed8-eb6da259a2d2'::uuid, $cat${"relationship": "referral_affiliate", "relationships": ["referral_affiliate"], "products": [], "size_tier": "small_mid", "paper": ["D", "all_credit"], "consolidation": {"type": "restructure", "confidence": "high", "note": "CORRECTS THE PREMISE: Value Capital Funding does NOT do reverse consolidation and actively campaigns against it. Their own blog calls reverse consolidations 'too good to be true', citing effective costs up to ~300% APR and the fact that they ADD debt rather than reduce it. Their position statement: 'At Value Capital Funding, we don't offer any MCA financing.' What they actually do: negotiate with the merchant's existing funders to cut payments 60-70% (often within 24 hours), and separately refinance into bank/FDIC-backed products. 90%+ claimed qualification rate, no upfront fees. Aimed at merchants in or near default. Also offers: refinancing into bank / FDIC-insured replacement financing Underwritten: N/A — they advance no capital at all Evidence: valuecapitalfunding.com blog 'MCA Reverse Consolidation: Too Good To Be True' (author Barry Kornfeld) plus their debt-reduction article stating outright they offer no MCA financing."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": true}, "known_for": "MCA debt relief and restructuring — cuts merchant payments by 60–70%", "deal_fit": "THE DISTRESSED-MERCHANT EXIT. When a lead is too stacked to fund — the exact profile the UCC lead book keeps surfacing — this is where the file goes instead of being written off. Pure referral: we hand off the merchant and collect a referral commission; we do not underwrite or submit a stip package.", "confidence": "high", "source_batch": "A", "website": "valuecapitalfunding.com", "amount_note": "N/A — does not advance capital. Restructures existing MCA debt; $100M+ of MCA debt restructured or refinanced to date.", "notes": "MISCLASSIFIED IN OUR DB — our record has product 'mca', implying they fund advances. THEY DO NOT. They are a debt-relief / restructuring firm that works the other side of the trade: reducing, restructuring, and refinancing MCA debt the merchant already carries, plus routing clients to FDIC-insured loans. Recommend recategorizing to a non-funding referral partner. This aligns with the platform's existing 'vcf' (debt relief) deal_type and the /debt-relief intake — Value Capital Funding is that product line's natural counterparty. Partner program CONFIRMED and explicitly built for our profile: 'designed exclusively for commercial loan brokers and referral agents', paying referral commissions. No upfront fees to the merchant; agreements often signed within 24 hours. Caution on the track record: they claim 30+ years experience, but Trustindex lists the company as founded 2025 with 1–10 employees, and Trustpilot shows 4 stars over only 57 reviews. Verify the entity's history and the written commission terms before routing volume."}$cat$::jsonb),
  ('07372c69-0fcb-4925-b95a-2dcb4e863e8a'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "mid_large", "paper": ["C", "D"], "consolidation": {"type": "none", "confidence": "low", "note": "Not advertised anywhere I could find — no consolidation or reverse-consolidation product page, and nothing in third-party directories. Treat as UNCONFIRMED rather than a hard no: plenty of MCA funders will quietly do a payoff or a reverse for the right file without marketing it. Ask the rep directly before ruling them out for a stacked merchant. Evidence: Absence of evidence after site scrape + targeted search; not a verified negative."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "Established NY MCA funder (CEO Jay Avigdor) with a well-run, heavily marketed ISO relations desk", "deal_fit": "Same-day mid-to-large MCA. Clear published bar: FICO 500+, $20K+ monthly revenue, 3 months of bank statements. Send the low-FICO merchant with solid deposits who needs money today.", "confidence": "high", "source_batch": "A", "website": "velocitycg.com", "amount_note": "Up to $2,000,000 same-day advertised; independent directory data puts the practical max at $750,000", "notes": "Quals verified on their site: 3 months bank statements, $20K minimum monthly revenue, FICO 500+, up to $2M same-day subject to underwriting. Institutionally backed — raised a $5M Series A plus a $10M credit line, and has been a deBanked featured provider since 2018 with an active ISO relations program (velocitycg.com/iso-relations). Directory data: FICO 500 floor, 24-hour funding, $750K max. Broad industry coverage including healthcare, retail, and technology. One of the more credible ISO-channel funders in this batch."}$cat$::jsonb),
  ('7f0397ba-6367-43de-8c77-113c016a9477'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder", "referral_affiliate"], "products": ["mca"], "size_tier": "micro", "paper": ["C", "D", "all_credit"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "Sub-$20K advances for gig workers, 1099s and solo operators, funded in minutes", "deal_fit": "Solo/1099/gig operator asking under $20K who has no bank-statement package worth building — refer them out, do not try to submit a file.", "confidence": "high", "source_batch": "B", "paper_note": "C/D — all-credit / no credit check. Revenue-based only; approval keys on deposits, overdrafts, negative days, avg daily balance.", "website": "gigglefinance.com", "min_amount": 1000, "max_amount": 20000, "amount_note": "Up to $15K new, $20K for repeat customers. Minimum not published.", "relationship_note": "Funds off its own book (revenue-based advance), but the broker channel is a pure REFERRAL program: the client applies directly on Giggle's site and the partner stays attributed. No package submission. Confirmed at gigglefinance.com/partnerships.", "requirements": "3+ months 1099/business income, business bank account, $3,000+ in account with 4+ deposits last month. NOT available in NY, CA, OR. W-2-only earners do not qualify."}$cat$::jsonb),
  ('e97890fb-1801-4335-ae96-4336dbfd05e0'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator", "referral_affiliate"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "equipment_financing", "real_estate_cre", "invoice_factoring"], "size_tier": "mid_large", "paper": ["A", "B", "C", "all_credit"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": true, "real_estate": true, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": false, "consolidation": false}, "known_for": "Broad business-financing marketplace with SBA, CRE and AR/PO reach", "deal_fit": "A bank-style request (SBA, LOC, equipment, CRE, AR/PO) we cannot place ourselves — but prefer a direct lender first, since sending a merchant here hands a live buyer to a competitor.", "confidence": "high", "source_batch": "B", "paper_note": "A/B/C — 500+ FICO, all credit types accepted", "website": "rok.biz", "min_amount": 10000, "max_amount": 5000000, "relationship_note": "COMPETING BROKER. Their own site meta calls them 'the top small business loan and services marketplace' — they shop deals to a lender network rather than funding off a balance sheet. No ISO-inbound program found; the relationship available to us is referral, not submission. Circumvention risk: they sell to the same merchants we do.", "requirements": "500+ FICO, 6 months in business, $10K+ monthly sales. Funding 1–45 days depending on product."}$cat$::jsonb),
  ('78735f53-19e3-4cb8-979d-c3b9eb9264c6'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "term_loan"], "size_tier": "mid_large", "paper": ["A", "B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "NYC direct funder for larger, cleaner A/B advances and term loans", "deal_fit": "Established merchant, 1+ year in business, 650+ FICO, clean statements, asking $25K+ — a bigger clean file, not a salvage job.", "confidence": "med", "source_batch": "B", "paper_note": "A/B — cleaner, more established files", "website": "altbanq.com", "min_amount": 25000, "max_amount": 10000000, "amount_note": "CONFLICT: third-party review (United Capital Source) says $25K–$10M with 650 FICO / 12mo TIB; Altbanq's own site implies a much lower floor (~$1K, 600 FICO, 6mo). Treat the UCS box as the real underwriting box and the site as marketing. Verify before promising a large number.", "relationship_note": "Founded 2014 as SOS Capital, rebranded to Altbanq. NYC direct funder with an ISO/partner program. Also sells payment processing.", "requirements": "~650 FICO, 12 months in business, ~$100K annual revenue (per UCS review). Same-day approval, next-day funding."}$cat$::jsonb),
