  ('be6d2ab2-b385-40a0-b15f-d35a84a56ce9'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "invoice_factoring", "line_of_credit", "term_loan"], "size_tier": "small_mid", "paper": ["C"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "One of the few funders covering Canada and Puerto Rico alongside the US", "deal_fit": "C-paper merchant needing $3K–$150K — and the go-to whenever a merchant is Canadian or in Puerto Rico, where most of our shelf can't help.", "confidence": "high", "source_batch": "B", "paper_note": "C — FICO 500+ on a soft pull", "website": "greenboxcapital.com", "min_amount": 3000, "max_amount": 500000, "amount_note": "Site headline says up to $500K; our internal note of $250K is the more typical MCA ceiling.", "relationship_note": "Dedicated ISO program page at /company/iso-program/ with an online application, and they market it as an 'ethical broker partnership'. Miami-based.", "requirements": "500+ FICO (soft pull), 5+ months in business, $10,000/mo revenue. Michigan requires 1+ year TIB. Canadian trucking requires $50,000/mo. Funding in 24 hours."}$cat$::jsonb),
  ('1f43a7e8-ebcd-4da1-91bd-f0e6ebe11f7e'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "real_estate_cre", "equipment_financing", "invoice_factoring"], "size_tier": "small_mid", "paper": ["A", "B", "C", "D"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": true, "real_estate": true, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Small Connecticut brokerage with a wide shelf including SBA and hard money", "deal_fit": "A CRE, hard-money or SBA request we cannot place ourselves — but prefer a direct lender, since this is another broker who will own the merchant relationship afterward.", "confidence": "med", "source_batch": "B", "paper_note": "A/B/C/D depending on product", "website": "grpfunding.com", "min_amount": 1000, "max_amount": 500000, "amount_note": "$500K applies to working capital; their CRE and SBA products would run higher.", "relationship_note": "INFERRED, not stated. A small Berlin CT shop on a Wix site advertising SBA 7(a)/504, CRE, new construction, hard-money fix & flip, multifamily, asset-based lending, invoice factoring AND cash advances. No single balance sheet covers that shelf — this is a broker's product menu. Address: 100 Harding Street, Berlin CT. Treat as a competing broker with the same circumvention caution as ROK.", "requirements": "Varies by product. Deposits as fast as the next business day."}$cat$::jsonb),
  ('5cda4eb9-eb51-4039-983a-55cea5ae920a'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["term_loan", "line_of_credit", "equipment_financing", "invoice_factoring"], "size_tier": "mid_large", "paper": ["A", "B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": true, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Established A/B-paper term lender with a long track record and strong merchant reviews", "deal_fit": "Send clean 1st-position files with real bank health that want an amortizing term loan or LOC instead of an advance.", "confidence": "high", "source_batch": "C", "website": "https://ioufinancial.com", "min_amount": 5000, "max_amount": 1500000, "amount_note": "Term loans up to $1,500,000, 6-24 month terms, daily/weekly/bi-weekly payments. Low end not published; $5K assumed floor.", "relationship_note": "Direct lender (not an MCA funder). Runs an 'IOU Preferred Partner' ISO/broker program with its own partner portal at app.ioufinancial.com/brokers/new.", "credit_note": "Clean-paper lender. 15+ years, $1.9B deployed across 17,000+ loans, Trustpilot 4.9/993. Not a bad-credit shop."}$cat$::jsonb),
  ('638c125e-49f9-4ae6-9d80-6e12081df653'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder", "marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "equipment_financing", "invoice_factoring"], "size_tier": "jumbo", "paper": ["A", "B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": true, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "Full-stack direct funder with a real SBA and equipment shelf plus a fallback broker network", "deal_fit": "One-stop for A/B files that could go term loan, LOC, SBA or equipment — good when you want multiple product shots from a single submission.", "confidence": "high", "source_batch": "C", "website": "https://kapitus.com", "min_amount": 5000, "max_amount": 5000000, "amount_note": "Site advertises $5K to $5M across the product set; third-party directories peg the practical revenue-based/term max nearer $1M with 24-hour funding.", "relationship_note": "Direct funder that also runs KapitusPLUS, a broader financing network it brokers into when the deal is outside its own box. Three partner tracks: Sales Partners (ISO/broker), Referral Partners, Equipment Provider Partners — kapitus.com/partner/. ISO program is explicitly named on the referral page.", "credit_note": "Min FICO around 525 per third-party directory — so B/C is reachable, but the A/B products (SBA, LOC, term) are the draw. Arlington VA, est. 2006."}$cat$::jsonb),
  ('46e6f8ac-1f0c-4bc3-a7a3-b56256feadaf'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "real_estate_cre", "equipment_financing", "invoice_factoring", "consumer"], "size_tier": "jumbo", "paper": ["A", "B", "C", "D"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": true, "real_estate": true, "micro": true, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false}, "known_for": "Free full-service aggregator that syndicates half of every deal it places", "deal_fit": "Best single outlet for a file you can't place yourself — especially CRE or residential referrals MFunding has no home for, and sub-FICO/startup MCA.", "confidence": "high", "source_batch": "C", "website": "https://lendersaccess.com", "min_amount": 5000, "max_amount": 50000000, "amount_note": "Per their published program table: MCA/ACH $5K-$500K; SBA 7(a) $50K-$5M; equipment $10K-$2M; factoring $25K-$5M; starter $5K-$50K; CRE bridge $500K-$30M; multifamily $1M-$50M+; residential $75K-$3M.", "relationship_note": "Sciascia Enterprises LLC DBA Lenders Access. Full-service aggregator/back office: you email one package to submit@lendersaccess.com, they stack it, run ONE soft pull shared to all bidding lenders, and route to 5-20 lenders. Free to brokers — they earn by syndicating 50-70% of every advance rather than splitting your commission. Commission paid lender-direct to the broker. Merchant identity redacted until an offer is picked; anti-circumvention clauses in their lender agreements. 1,700 brokers, $325M deployed, 25,145 loans funded, 98+ programs.", "credit_note": "Explicit sub-FICO and starter/startup programs alongside SBA — the full spread. All-credit OK."}$cat$::jsonb),
  ('8530b99a-80d2-4c42-9889-62ff6a6ba125'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator", "referral_affiliate"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "equipment_financing", "invoice_factoring", "real_estate_cre"], "size_tier": "jumbo", "paper": ["A", "B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": true, "real_estate": true, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false}, "known_for": "The dominant SMB lending marketplace and the default comparison shopper for merchants", "deal_fit": "Referral-only outlet; do not route live MCA leads here — they own the merchant relationship once submitted.", "confidence": "med", "source_batch": "C", "website": "https://www.lendio.com", "min_amount": 5000, "max_amount": 5000000, "amount_note": "Revenue-based financing published at $5K-$2M; SBA and CRE go higher. Ranges vary by the underlying lender, not by Lendio.", "relationship_note": "The largest small-business lending marketplace. Lendio Partners, LLC is a licensed finance lender/broker; their own disclosure states compensation may be received from lenders for referrals or funded loans and may affect placement. For MFunding this is a referral OUTLET and a direct competitor for the same merchant, not a funder — treat any relationship as outbound referral only.", "credit_note": "Panel spans clean SBA paper down to sub-600 RBF. D paper generally falls off the platform."}$cat$::jsonb),
  ('9e913a4c-66cd-4265-8dcf-0f42b919bfd0'::uuid, $cat${"relationship": "white_label", "relationships": ["white_label", "marketplace_aggregator"], "products": ["mca", "term_loan", "line_of_credit", "sba_loan", "equipment_financing"], "size_tier": "mid_large", "paper": ["A", "B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": true, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": false, "consolidation": false}, "known_for": "Free broker-side origination software with a bundled 50+ lender panel and no commission split", "deal_fit": "Evaluate as a submission tool / secondary lender panel, not as a funder — overlaps heavily with what MFunding already built in React+Supabase.", "confidence": "med", "source_batch": "C", "website": "https://levr.ai", "amount_note": "No amounts of its own — determined entirely by the panel lender that takes the deal.", "relationship_note": "NOT a funder — it is free software for business loan brokers. AI-powered origination platform that connects a broker to 50+ small business lenders, and they advertise that you keep 100% of commissions with no split. Some panel lenders accept applications only through Levr. Signup at portal.levr.ai/signup.", "credit_note": "Depends on panel lender; not a credit box of its own."}$cat$::jsonb),
  ('0d5c987e-540a-4956-9e49-d4a282447231'::uuid, $cat${"relationship": "marketplace_aggregator", "relationships": ["marketplace_aggregator", "referral_affiliate"], "products": ["real_estate_cre", "consumer", "term_loan"], "size_tier": "jumbo", "paper": ["A", "B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": true, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": false, "consolidation": false}, "known_for": "Non-QM and DSCR real-estate lending for investors and self-employed borrowers", "deal_fit": "Only for real-estate-backed referrals (CRE bridge, DSCR rental, investor non-QM) — no fit for an MCA file.", "confidence": "med", "source_batch": "C", "website": "https://lionsford.com", "min_amount": 150000, "max_amount": 25000000, "amount_note": "CRE page publishes $150K-$25M, 6-24 month term, up to 70% LTV.", "relationship_note": "Irvine, CA. Presents as a commercial lender but their own fee disclosure reads like a broker: 'Upon successfully obtaining and delivering a business loan, line of credit, or other financial product to the borrower, Lionsford LLC will charge the borrower a one-time service fee of 2.67% of the overall funding amount provided by the lender.' ⚠️ COMPLIANCE FLAG: that is a merchant-paid fee, which conflicts with MFunding's 'no upfront fees / we are paid by the funder' positioning — vet before routing any merchant here.", "credit_note": "Non-QM / self-employed / investor niche — asset-driven rather than FICO-driven."}$cat$::jsonb),
