  ('9b24fce7-f43f-4021-8a0b-97900f2300fc'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["B", "C"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": false}, "known_for": "MCA funder with a retail peer-to-peer syndication marketplace bolted on (min $100 investment)", "deal_fit": "A genuine MCA outlet with a live ISO program (iso.merchantmarketplace.com) - worth onboarding for B/C-paper files. Uniondale NY.", "confidence": "medium", "source_batch": "D", "paper_note": "B/C", "website": "https://merchantmarketplace.com", "min_amount": 5000, "max_amount": 500000, "amount_note": "No published per-deal range on the homepage; the funding side is MCA-only. The distinguishing feature is the retail syndication side - outside investors put in from $100 to participate in the advances.", "notes": "Founder Adam (prev. CEO/CTO of Velocity Group USA, ~$200M funded in four years) - real MCA pedigree. The 'marketplace' label refers to INVESTORS buying into deals, not to brokering deals out, so relationship is direct_funder despite the name. Per-deal amounts unpublished.", "credit_note": "'When banks say no, The Merchant Marketplace says yes' - explicitly a decline-market funder."}$cat$::jsonb),
