  ('bf786d56-b811-4bb1-b5a3-b75168a2cfa2'::uuid, $cat${"relationship": "equipment_lessor", "relationships": ["equipment_lessor"], "products": ["equipment_financing", "term_loan"], "size_tier": "small_mid", "paper": ["B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": true, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": true}, "known_for": "Small-ticket truck & specialty equipment financing/leasing since 1990 (tow, boom, septic, landscaping trucks; embroidery & screen-printing presses); $1.73B financed", "deal_fit": "Merchant is buying a specific truck or specialty machine (new or used, vendor or private party) and wants 36-84 month payments — refer here, do not try to force an MCA.", "confidence": "high", "source_batch": "E", "paper_note": "B", "website": "https://www.beaconfunding.com", "min_amount": 5000, "max_amount": 250000, "notes": "Vertical-specialist lessor, Chicago-based. Has a vendor-financing program (equipment dealers) and a 'working capital' add-on program. Amount range inferred from small-ticket positioning — not published; treat min/max as approximate.", "credit_note": "Approves ~7 of 10 applications and explicitly welcomes start-ups — softer credit box than a bank, but it is collateral-driven (the equipment secures the deal), not revenue-driven."}$cat$::jsonb),
  ('bfdfc61c-54f4-47cb-8090-14d14545144e'::uuid, $cat${"relationship": "referral_affiliate", "relationships": ["referral_affiliate"], "products": ["startup_robs_401k", "sba_loan", "equipment_financing", "term_loan"], "size_tier": "mid_large", "paper": ["A"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": true, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": false, "consolidation": false, "factoring": false, "equipment": true}, "known_for": "Pioneer of ROBS (Rollover as Business Startup) 401k funding — the Rainmaker Plan / ROBS+; heavy franchise-financing focus, 30,000+ entrepreneurs, ~40 years", "deal_fit": "Pre-revenue startup or franchise buyer with a sizable 401k/IRA and no business bank history — the one lane MCA cannot serve.", "confidence": "high", "source_batch": "E", "paper_note": "A", "website": "https://www.benetrends.com", "min_amount": 50000, "max_amount": 5000000, "notes": "Not a funder in the MCA sense: they administer ROBS plans and place SBA loans with partner banks (they explicitly market 'we found multiple banks who provide SBA funding'). Also offer QuickStart unsecured loans, fleet/equipment leasing, and paid business-plan services. Lansdale PA. Zero overlap with the MCA pipeline — treat strictly as a referral outlet for startup/franchise leads.", "credit_note": "ROBS is not credit-underwritten at all (the merchant funds themselves from their own 401k/IRA); the SBA side is full A-paper bank underwriting."}$cat$::jsonb),
  ('e1bafe81-c251-4d76-8715-b3f2df8ab1e6'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": false}, "known_for": "Small independent MCA shop — 24-hour funding, custom underwriting for SMB cash-flow needs", "deal_fit": "Small-to-mid merchant needing fast working capital where a bigger funder's box is too tight; expect a hands-on, one-off underwrite.", "confidence": "low", "source_batch": "E", "paper_note": "B", "website": "https://www.broadwayadvance.com", "min_amount": 10000, "max_amount": 250000, "notes": "Thin Wix-built site with no published amounts, credit minimums, position policy, or ISO/partner page. Title tag literally reads 'Broadway Advance LLC | MCA'. Size tier and paper tier are inferred from the shop's profile, not stated. Verify terms directly with the funder before relying on this record.", "credit_note": "Revenue-based, explicitly 'without the need for traditional loans' — underwrites bank deposits, not FICO. Amounts and credit floor are not published."}$cat$::jsonb),
  ('922b4679-4d19-4df2-b0d1-9bc8a19c1aff'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "small_mid", "paper": ["C"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": true, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": false}, "known_for": "High-volume NY MCA funder — $1.75B funded, 30,000+ businesses, same-day approvals, 4.7 Trustpilot", "deal_fit": "Credit-impaired merchant (525-600 FICO) with real deposits who needs up to $500K and cannot clear an A-paper box.", "confidence": "high", "source_batch": "E", "paper_note": "C", "website": "https://byzfunder.com", "min_amount": 5000, "max_amount": 500000, "notes": "Site was recently rebuilt (Lovable-hosted) with a heavy SEO content library — the shop is very much active. Factor rates in their own material run 1.20-1.60, consistent with B/C paper.", "credit_note": "Accepts 525+ credit (their own guides cite 550+ as the general MCA floor and 570/$12K monthly revenue for the easiest approvals); ~6 months of consistent revenue and $7,500-$10,000/mo minimum depending on profile. No hard pull."}$cat$::jsonb),
  ('dd476558-074e-42ea-945b-cc1bffe2e879'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["term_loan", "mca", "equipment_financing"], "size_tier": "mid_large", "paper": ["B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": true}, "known_for": "One of the original MCA/daily-remittance funders (est. 1998); now positions as working-capital loans $2,500-$400,000 plus equipment financing", "deal_fit": "Established merchant wanting a conventional-feeling working capital loan up to ~$400K with a name-brand, long-tenured funder.", "confidence": "high", "source_batch": "E", "paper_note": "B", "website": "https://www.cancapital.com", "min_amount": 2500, "max_amount": 400000, "notes": "Homepage body cites $2,500-$400,000 while the meta description still says 'up to $350K' — the published ceiling is inconsistent; confirm the live box. CAN's product language has migrated from 'merchant cash advance' to 'working capital loan', so compliance-check which product a given approval actually is before using loan terminology with the merchant.", "credit_note": "Legacy revenue-based underwriter, 28 years and 90,000+ businesses funded; modern marketing is loan-framed rather than MCA-framed."}$cat$::jsonb),
