  ('04b9a2dc-4921-49ca-8dad-ded8ecbb4896'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["line_of_credit"], "size_tier": "small_mid", "paper": ["A"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": true, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": false}, "known_for": "'True Line of Credit' — revolving, draw-as-needed, no prepayment penalty, interest saved on early payoff; backed by Enova International", "deal_fit": "Cleaner-credit merchant who wants revolving flexibility for recurring cash-flow gaps rather than a lump sum — and can wait a day, not an hour.", "confidence": "high", "source_batch": "E", "paper_note": "A", "website": "https://www.headwaycapital.com", "min_amount": 5000, "max_amount": 100000, "notes": "Enova-owned, same parent as OnDeck and CashNetUSA — so Headway and OnDeck are effectively sibling products; submitting the same merchant to both is likely redundant. This is a LOAN product: standard lending terminology is correct and MCA language must not be used. State-licensed lender, so availability varies by state. Amount range is the widely published $5K-$100K; the homepage itself gates the limit behind a calculator.", "credit_note": "Soft pull to check eligibility (no impact on credit score). Bank-style A/B underwriting — a true revolving line, not a receivables purchase."}$cat$::jsonb),
