  ('592a7744-0267-4d4a-8edf-f0c9bfc9d0ac'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca"], "size_tier": "jumbo", "paper": ["A"], "consolidation": {"type": "true_consolidation/payoff", "confidence": "med", "note": "Research note: 'Also runs consolidations at that size band' ($500K-$10M A-paper). Large-ticket only."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": true, "high_risk_dpaper": false, "fast_funding": false, "consolidation": true, "factoring": false, "equipment": false}, "known_for": "Large-ticket short-term revenue-based financing, $500K-$10M — the top end of the RBF market; Greenwich CT, institutional posture", "deal_fit": "A rare, high-quality merchant needing $500K+ that is far too large for a standard MCA funder — this is the escalation path, not the default.", "confidence": "high", "source_batch": "E", "paper_note": "A", "website": "https://libertasfunding.com", "min_amount": 500000, "max_amount": 10000000, "notes": "MINIMUM CORRECTION: the site states $500K-$10M, not the $100K-$10M in the brief. That floor matters — a typical $50K MFunding deal is 10x too small and would be an instant decline, which is very likely why this relationship went dormant. Only worth reactivating if the pipeline starts producing genuine seven-figure-revenue merchants. Also runs consolidations at that size band.", "credit_note": "A-paper only. Targets SMBs 'on a growth trajectory' — strong financials, real books, typically institutional-quality files. Credit-impaired or stacked merchants will not clear."}$cat$::jsonb),
  ('276bc36a-2b0d-4ea2-b487-9502bd562137'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["term_loan", "mca", "equipment_financing"], "size_tier": "mid_large", "paper": ["B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": true, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": true}, "known_for": "Long-established San Diego direct funder — working capital $6,000-$500,000 plus equipment financing up to $150,000, next-business-day funding, US-based specialists", "deal_fit": "Mainstream mid-market merchant wanting up to $500K working capital, or a smaller equipment purchase up to $150K, from a stable name-brand funder.", "confidence": "high", "source_batch": "E", "paper_note": "B", "website": "https://www.nationalfunding.com", "min_amount": 6000, "max_amount": 500000, "notes": "Amounts confirmed live on the homepage. Product is marketed as a working capital LOAN — verify per-approval whether the executed contract is a loan or a receivables purchase before choosing merchant-facing language. 4.6/5 Trustpilot.", "credit_note": "Eligibility check is a soft pull with no credit-score impact. Positions itself on understanding the business story rather than pure risk scoring — practical B-paper box."}$cat$::jsonb),
  ('c621ffe2-0766-42c8-82bc-57954e523ebb'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["mca", "term_loan"], "size_tier": "small_mid", "paper": ["B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": false, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": false}, "known_for": "Tech-and-data-driven alternative lending platform built around its ISO channel — 1,200+ ISO partners, fast commission payments, real-time funding status for brokers", "deal_fit": "Standard small-to-mid working-capital deal, especially contractors and trade businesses, where the ISO wants transparent status and quick commission turnaround.", "confidence": "medium", "source_batch": "E", "paper_note": "B", "website": "https://gonexi.com", "min_amount": 10000, "max_amount": 500000, "notes": "IDENTITY CORRECTION — the brief's nexi.com is the WRONG COMPANY. nexi.com / nexigroup.com is Nexi Group, the large Italian/European PAYMENTS processor, which does no US small-business lending. The MFunding counterparty is Nexi Finance at gonexi.com (1-800-499-NEXI), a US alternative lender with a dedicated ISO/Broker program and a Director of ISO Relations. Verify the record's stored URL. Amount range is inferred from their positioning and third-party reviews (UnitedCapitalSource), not published — hence medium confidence. Partner page content dates to 2023.", "credit_note": "Alternative/revenue-based underwriting with sector-tailored programs (contractors and similar trades called out explicitly). Specific credit and revenue floors are not published."}$cat$::jsonb),
  ('2e5ad2d4-07c8-4b23-97b4-c96920e0c022'::uuid, $cat${"relationship": "direct_funder", "relationships": ["direct_funder"], "products": ["term_loan", "line_of_credit"], "size_tier": "small_mid", "paper": ["B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": true, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false, "factoring": false, "equipment": false}, "known_for": "Category-defining online small-business lender (Enova-owned) — term loans and revolving lines of credit, same-day funding, free business credit score", "deal_fit": "Merchant with 1+ years of history and decent credit who qualifies for a real loan or line and would be overpaying on an MCA.", "confidence": "high", "source_batch": "E", "paper_note": "B", "website": "https://www.ondeck.com/partner", "min_amount": 5000, "max_amount": 250000, "notes": "Partner program requires 2+ years in business and a secured functioning website FOR THE ISO/BROKER — an onboarding gate MFunding must meet, and a plausible reason this relationship sits inactive at an early-stage brokerage. Enova-owned, sibling to Headway Capital — overlapping boxes, do not double-submit. LOAN product: standard lending terminology applies, MCA 'advance' language is wrong here. Term loans commonly $5K-$250K with lines up to ~$100K; the partner page itself does not restate amounts.", "credit_note": "Eligibility check does not affect personal credit. Reports loan activity to business credit bureaus, so it actively builds the merchant's business credit — a real differentiator vs. an MCA."}$cat$::jsonb),
  ('848dae60-cad7-4afe-9970-4dd5e281cb2a'::uuid, $cat${"relationship": "factoring_company", "relationships": ["factoring_company"], "products": ["invoice_factoring"], "size_tier": "small_mid", "paper": ["B"], "consolidation": {"type": "none", "confidence": "low", "note": "No consolidation product identified in this research pass. Treat as unconfirmed, not a hard no."}, "flags": {"sba": false, "real_estate": false, "micro": false, "first_position_only": true, "high_risk_dpaper": false, "fast_funding": true, "consolidation": false, "factoring": true, "equipment": false}, "known_for": "Freight/trucking invoice factoring plus freight payments and banking — now part of the unified 'Triumph Network' platform for carriers, shippers, brokers and factors", "deal_fit": "Trucking carrier or freight broker with unpaid invoices who needs cash flow today — refer, do not advance against it.", "confidence": "high", "source_batch": "E", "paper_note": "B", "website": "https://triumph.io", "min_amount": 5000, "max_amount": 1000000, "notes": "CONFIRMS THE HYPOTHESIS IN THE BRIEF: freight/trucking factoring, not MCA. REBRANDED — triumphbusinesscapital.com now redirects to triumph.io (Triumph Financial); the Business Capital name has been folded into the Triumph Network, so stored contacts/agreements under the old name are likely stale. Important interaction with MCA: a merchant already factoring receivables with Triumph has a UCC lien on those receivables, which conflicts with an MCA position — screen for it. Invoice-level amounts vary widely; min/max are indicative only.", "credit_note": "Factoring underwrites the DEBTOR (the shipper/broker paying the invoice), not the carrier — so a credit-impaired trucking company with creditworthy customers is very fundable."}$cat$::jsonb)
